fn copyto<T: Copy>(dst: Vec<T>, src: Vec<T>, mask: Vec<bool>) -> Vec<T> {
    // Requires: The lengths of dst, src, and mask must be the same.
    // Ensures: The result vector will have the same length as dst, 
    // and for each index i, if mask[i] is true, result[i] will be src[i], 
    // otherwise result[i] will be dst[i].
    // Decreases: The length of dst, src, and mask.
    // Invariant: The result vector is being built correctly according to the mask.
    // 
    // Requires: dst.len() == src.len() && dst.len() == mask.len()
    // Ensures: result.len() == dst.len()
    // Ensures: forall(i: usize :: 0 <= i && i < dst.len() ==> 
    //     (mask[i] ==> result[i] == src[i]) && (!mask[i] ==> result[i] == dst[i]))
    let mut result = Vec::with_capacity(dst.len());

    // Iterate over the indices of the arrays
    for i in 0..dst.len() {
        // Check the mask and select the appropriate element
        // Assert: 0 <= i < dst.len()
        assert!(i < dst.len());
        
        if mask[i] {
            result.push(src[i]);
        } else {
            result.push(dst[i]);
        }
    }

    result
}